import 'package:flutter/material.dart';
class AppScaffold extends StatelessWidget {final Widget body;final int index;final ValueChanged<int> onTab;final String? title;const AppScaffold({super.key,required this.body,required this.index,required this.onTab,this.title});@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:title==null?null:AppBar(title:Text(title!)),body:SafeArea(child:body),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:onTab,destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'خانه'),NavigationDestination(icon:Icon(Icons.kitchen_outlined),label:'انبار'),NavigationDestination(icon:Icon(Icons.favorite_border),label:'علاقه‌مندی‌ها'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'تنظیمات')])));}
class PrimaryButton extends StatelessWidget {final String text;final VoidCallback onPressed;const PrimaryButton({super.key,required this.text,required this.onPressed});@override Widget build(BuildContext c)=>SizedBox(width:double.infinity,child:FilledButton(onPressed:onPressed,child:Padding(padding:const EdgeInsets.all(12),child:Text(text))));}
class SectionTitle extends StatelessWidget {final String text;const SectionTitle(this.text,{super.key});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.symmetric(vertical:12),child:Text(text,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold,color:Color(0xFF1E4D38))));}
class ChipPill extends StatelessWidget {final String label;final bool selected;final VoidCallback onTap;const ChipPill({super.key,required this.label,required this.selected,required this.onTap});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsetsDirectional.only(end:8),child:ChoiceChip(label:Text(label),selected:selected,onSelected:(_)=>onTap()));}
class EmptyState extends StatelessWidget {final String message;const EmptyState(this.message,{super.key});@override Widget build(BuildContext c)=>Center(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.spa_outlined,size:52,color:Color(0xFF84A98C)),const SizedBox(height:12),Text(message,textAlign:TextAlign.center)])));}
